import contextlib
import threading

import torch
import torch.distributed as dist

from .distributed import is_global_main_process, print_on_global_main

try:
    import hfai

    HAS_HFAI = True
except ModuleNotFoundError:
    hfai = None
    HAS_HFAI = False


class SuspendController:
    def __init__(self, device, poll_interval_seconds: float = 1.0):
        self.device = device
        self.poll_interval_seconds = float(poll_interval_seconds)
        self._requested = threading.Event()
        self._stop_requested = threading.Event()
        self._monitor_thread = None
        self._suspend_flag = torch.zeros(1, device=self.device, dtype=torch.int32)

    def _monitor_suspend(self):
        print_on_global_main("Start monitoring hfai suspend signal...")
        while not self._stop_requested.is_set():
            if hfai.client.receive_suspend_command():
                print_on_global_main("Received hfai suspend command!")
                self._requested.set()
                return
            self._stop_requested.wait(timeout=self.poll_interval_seconds)

    @contextlib.contextmanager
    def monitoring(self):
        if not HAS_HFAI:
            yield self
            return

        try:
            self._requested.clear()
            self._stop_requested.clear()
            if is_global_main_process():
                self._monitor_thread = threading.Thread(
                    target=self._monitor_suspend,
                    daemon=True,
                )
                self._monitor_thread.start()
            yield self
        finally:
            self._stop_requested.set()
            if self._monitor_thread is not None:
                self._monitor_thread.join(timeout=self.poll_interval_seconds + 1.0)
                self._monitor_thread = None

    def requested(self) -> bool:
        if not HAS_HFAI:
            return False

        dist.barrier()
        if is_global_main_process():
            self._suspend_flag[0] = 1 if self._requested.is_set() else 0
        dist.broadcast(self._suspend_flag, src=0)
        return bool(self._suspend_flag.item())

    def go_suspend(self):
        if not HAS_HFAI:
            raise RuntimeError("hfai is not available; cannot suspend the job.")
        hfai.client.go_suspend()

import torch
from torch.optim.lr_scheduler import CosineAnnealingLR as _CosineAnnealingLR
from torch.optim.lr_scheduler import LRScheduler as _LRScheduler


class TwoStageScheduler(_LRScheduler):
    def __init__(self, optimizer, after_scheduler: _LRScheduler, last_epoch=-1):
        self.after_scheduler = after_scheduler
        self.finished = False
        super().__init__(optimizer, last_epoch)

    def state_dict(self):
        state_dict = {
            key: value for key, value in self.__dict__.items() if key != "optimizer"
        }
        if isinstance(state_dict["after_scheduler"], _LRScheduler):
            state_dict["after_scheduler_type"] = type(
                state_dict["after_scheduler"]
            ).__name__
            state_dict["after_scheduler_dict"] = state_dict[
                "after_scheduler"
            ].state_dict()
            del state_dict["after_scheduler"]
        else:
            raise NotImplementedError()
        return state_dict

    def load_state_dict(self, state_dict):
        self.after_scheduler.load_state_dict(state_dict["after_scheduler_dict"])
        state_dict = {
            key: value
            for key, value in state_dict.items()
            if key not in ("after_scheduler_type", "after_scheduler_dict")
        }
        super().load_state_dict(state_dict)


class WarmupScheduler(TwoStageScheduler):
    def __init__(self, optimizer, warmup_epochs, after_scheduler, last_epoch=-1):
        self.warmup_epochs = int(warmup_epochs)
        super().__init__(optimizer, after_scheduler, last_epoch)

    def get_lr(self):
        if self.last_epoch >= self.warmup_epochs:
            if not self.finished:
                self.after_scheduler.base_lrs = self.base_lrs
                self.finished = True
            return self.after_scheduler.get_lr()

        return [(self.last_epoch + 1) / self.warmup_epochs * lr for lr in self.base_lrs]

    def step(self, epoch=None):
        if self.finished:
            if epoch is None:
                self.after_scheduler.step(None)
                self._last_lr = self.after_scheduler.get_last_lr()
            else:
                self.after_scheduler.step(epoch - self.warmup_epochs)
                self._last_lr = self.after_scheduler.get_last_lr()
        else:
            return super().step(epoch)


class CosineAnnealingWarmupLR(WarmupScheduler):
    def __init__(
        self,
        optimizer,
        total_steps: int,
        warmup_steps: int = 0,
        eta_min: float = 0.0,
        last_epoch: int = -1,
    ):
        base_scheduler = _CosineAnnealingLR(
            optimizer,
            total_steps - warmup_steps,
            eta_min=eta_min,
            last_epoch=last_epoch,
        )
        super().__init__(optimizer, warmup_steps, base_scheduler, last_epoch=last_epoch)


class BF16Optimizer:
    # Adapted from SpecForge/specforge/optimizer.py:BF16Optimizer.
    def __init__(
        self,
        model,
        lr,
        total_steps,
        warmup_ratio,
        weight_decay=0.0,
    ):
        self.model = model
        self.model_params = [p for p in model.parameters() if p.requires_grad]
        self.fp32_params = [
            p.detach().clone().to(torch.float32) for p in self.model_params
        ]
        for param in self.fp32_params:
            param.requires_grad = True
        self.optimizer = torch.optim.AdamW(
            self.fp32_params, lr=lr, weight_decay=weight_decay
        )
        self.scheduler = CosineAnnealingWarmupLR(
            self.optimizer,
            total_steps=total_steps,
            warmup_steps=int(warmup_ratio * total_steps),
        )

    def step(self):
        with torch.no_grad():
            for model_param, master_param in zip(self.model_params, self.fp32_params):
                master_param.grad = (
                    model_param.grad.detach().to(torch.float32)
                    if model_param.grad is not None
                    else None
                )
        self.optimizer.step()
        self.optimizer.zero_grad()
        self.scheduler.step()
        with torch.no_grad():
            for model_param, master_param in zip(self.model_params, self.fp32_params):
                model_param.data.copy_(master_param.data.to(model_param.dtype))
                model_param.grad = None

    def state_dict(self):
        return {
            "optimizer_state_dict": self.optimizer.state_dict(),
            "scheduler_state_dict": self.scheduler.state_dict(),
            "fp32_params": [param.detach().cpu() for param in self.fp32_params],
        }

    def load_state_dict(self, state_dict):
        self.optimizer.load_state_dict(state_dict["optimizer_state_dict"])
        self.scheduler.load_state_dict(state_dict["scheduler_state_dict"])
        fp32_params = state_dict["fp32_params"]
        for dst, src in zip(self.fp32_params, fp32_params):
            dst.data.copy_(src.to(dst.device))
        with torch.no_grad():
            for model_param, master_param in zip(self.model_params, self.fp32_params):
                model_param.data.copy_(master_param.data.to(model_param.dtype))

    def get_learning_rate(self):
        return self.optimizer.param_groups[0]["lr"]

from deepspec.data import CacheCollator
from deepspec.modeling.dspark.gemma4 import Gemma4DSparkModel
from deepspec.modeling.dspark.gemma4.config import (
    build_draft_config as build_gemma4_draft_config,
)
from deepspec.modeling.dspark.loss import compute_dspark_loss
from deepspec.modeling.dspark.qwen3 import Qwen3DSparkModel
from deepspec.modeling.dspark.qwen3.config import (
    build_draft_config as build_qwen3_draft_config,
)
from deepspec.trainer.base_trainer import BaseTrainer


class Qwen3DSparkTrainer(BaseTrainer):
    data_collator_cls = CacheCollator

    def _build_draft_model(self, *, target_config, model_args):
        draft_config = build_qwen3_draft_config(
            target_config=target_config,
            model_args=model_args,
        )
        return Qwen3DSparkModel(draft_config)

    # Training step.
    def run_batch(self, batch):
        outputs = self.model(
            input_ids=batch["input_ids"],
            target_hidden_states=batch["target_hidden_states"],
            loss_mask=batch["loss_mask"],
            target_last_hidden_states=batch["target_last_hidden_states"],
        )
        loss = compute_dspark_loss(
            outputs=outputs,
            loss_decay_gamma=self.args.model.loss_decay_gamma,
            ce_loss_alpha=float(self.args.model.ce_loss_alpha),
            l1_loss_alpha=float(self.args.model.l1_loss_alpha),
            confidence_head_alpha=float(self.args.model.confidence_head_alpha),
        )
        return loss


class Gemma4DSparkTrainer(Qwen3DSparkTrainer):
    def _build_draft_model(self, *, target_config, model_args):
        draft_config = build_gemma4_draft_config(
            target_config=target_config,
            model_args=model_args,
        )
        return Gemma4DSparkModel(draft_config)
